import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker, InventoryDecision } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Alpha", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Beta", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart – line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and tracks quantity", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.quantity).toBe(5);
  });

  it("tracks separate products independently", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
      "Product nonexistent is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot returns deep copies", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart should be unaffected
    expect(cart.itemCount).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

describe("Cart – pricing pipeline with defaults", () => {
  it("computes subtotal as sum of price * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });
});

describe("Cart – pricing pipeline with mocked seams", () => {
  it("applies discount → tax on discounted subtotal → shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(150),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };

    const cart = new Cart({
      discountPolicy,
      taxCalculator,
      shippingCalculator,
      region: "US-CA",
    });
    cart.add(productA, 5); // subtotal = 5000

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(500);

    // Tax should be computed on discounted subtotal (5000 - 500 = 4500)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
    expect(totals.taxCents).toBe(150);

    // Shipping receives lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      4500,
    );
    expect(totals.shippingCents).toBe(300);

    // total = discounted subtotal + tax + shipping = 4500 + 150 + 300
    expect(totals.totalCents).toBe(4950);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount policy returns more than subtotal
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.shippingCents).toBe(0);
  });

  it("uses US as default region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart – async checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
  });

  it("returns totals and lines without collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500) // new price for productA
        .mockResolvedValueOnce(2500), // new price for productB
    };
    const result = await cart.checkout({ priceFetcher });
    // New subtotal: 1500*2 + 2500*1 = 5500
    expect(result.totals.subtotalCents).toBe(5500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(result.lines[1]!.product.unitPriceCents).toBe(2500);
  });

  it("throws InventoryError when item unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.message).toBe("discontinued");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1, // less than requested 2
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.available).toBe(1);
    }
  });

  it("passes when inventory is sufficient", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 100,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(4000);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("uses default message when no reason provided", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).message).toContain("insufficient stock");
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000), // 1000 off
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10), // 10%
    };

    const cartWithSeams = new Cart({ discountPolicy, shippingCalculator });
    cartWithSeams.add(productA, 2); // subtotal = 2000
    // discounted = 2000 - 1000 = 1000, tax = 10% of 1000 = 100

    const result = await cartWithSeams.checkout({ asyncTaxProvider });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1600); // 1000 + 100 + 500
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 999,
      } satisfies InventoryDecision),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05), // 5%
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // Refreshed subtotal: 500*2 + 500*1 = 1500
    expect(result.totals.subtotalCents).toBe(1500);
    // tax = 5% of 1500 = 75
    expect(result.totals.taxCents).toBe(75);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API error",
    );
  });
});

